window.NARRATION = {"n_G0": {"dur": 9.68, "text": "Hi, and thanks for being here. This first part sets up your season. It takes about fifteen minutes, and you only do it once. Select Start when you're ready.", "sents": [[0, "Hi, and thanks for being here.", 0], [2.37, "This first part sets up your season.", 1], [4.71, "It takes about fifteen minutes, and you only do it once.", 1], [8.23, "Select Start when you're ready.", 2]], "cues": [0, 2.37, 8.23]}, "n_G2": {"dur": 21.6, "text": "Before you meet your Head Coach, here's an idea to keep with you all season. Performance is not determined by what you know. It is determined by what you can summon under pressure. That's Dr. Michael Platt, who directs the Wharton Neuroscience Initiative and wrote the foreword to Melissa's book. When you're ready, select Meet your Head Coach.", "sents": [[0.01, "Before you meet your Head Coach, here's an idea to keep with you all season.", 0], [5.11, "Performance is not determined by what you know.", 1], [7.99, "It is determined by what you can summon under pressure.", 1], [12.07, "That's Dr. Michael Platt, who directs the Wharton Neuroscience Initiative and wrote the foreword to Melissa's book.", 2], [19.11, "When you're ready, select Meet your Head Coach.", 3]], "cues": [0.01, 5.11, 12.07, 19.11]}, "n_G4": {"dur": 6.16, "text": "Carrie Fenton at Avanos has a short message for you about why your organization chose this season for its leaders.", "sents": [[0, "Carrie Fenton at Avanos has a short message for you about why your organization chose this season for its leaders.", 0]], "cues": [0]}, "n_G5": {"dur": 45.04, "text": "Let's set up your season. First comes the pre-assessment. It takes about five minutes, and it opens on the next screen. Next, download your Athleader Playbook. Your drills and reflections for every lesson live in it, so save it somewhere you'll find it again. Then get the agenda for your Starting Line meeting. That's a thirty-minute conversation with your Player-Coach about what you're working toward, and your Player-Coach will set it up. Last, block one hour a week for this course. Pick Google Calendar or Outlook and the hour goes straight into your calendar, or use the other option for Apple and anything else. Move the hour when you need to, as long as you keep it. Select Next when you're ready to start your pre-assessment.", "sents": [[0.09, "Let's set up your season.", 0], [1.97, "First comes the pre-assessment.", 1], [4.31, "It takes about five minutes, and it opens on the next screen.", 1], [7.93, "Next, download your Athleader Playbook.", 2], [10.95, "Your drills and reflections for every lesson live in it, so save it somewhere you'll find it again.", 2], [16.59, "Then get the agenda for your Starting Line meeting.", 3], [19.99, "That's a thirty-minute conversation with your Player-Coach about what you're working toward, and your Player-Coach will set it up.", 3], [26.91, "Last, block one hour a week for this course.", 4], [30.77, "Pick Google Calendar or Outlook and the hour goes straight into your calendar, or use the other option for Apple and anything else.", 4], [38.71, "Move the hour when you need to, as long as you keep it.", 4], [42.21, "Select Next when you're ready to start your pre-assessment.", 5]], "cues": [0.09, 1.97, 7.93, 16.59, 26.91, 42.21]}, "n_G7": {"dur": 41.52, "text": "People often ask about their Player-Coach at this point, so here are the answers. If your manager isn't taking part, that's okay. Your Player-Coach doesn't have to be your direct manager. You might report to more than one manager, or have none taking part at all, so choose a peer, a mentor or a colleague you trust. Whenever you see Player-Coach, think of that person. Only managers your company selects will have access to the manager track. If you manage several people who are taking part, hold one thirty-minute Commitment Meeting with each of them at the start. After that, build the fifteen-minute check-ins into meetings you already have, so there's nothing extra to schedule.", "sents": [[0, "People often ask about their Player-Coach at this point, so here are the answers.", 0], [4.85, "If your manager isn't taking part, that's okay.", 1], [8.11, "Your Player-Coach doesn't have to be your direct manager.", 1], [11.31, "You might report to more than one manager, or have none taking part at all, so choose a peer, a mentor or a colleague you trust.", 1], [19.91, "Whenever you see Player-Coach, think of that person.", 1], [23.53, "Only managers your company selects will have access to the manager track.", 1], [27.23, "If you manage several people who are taking part, hold one thirty-minute Commitment Meeting with each of them at the start.", 2], [35.17, "After that, build the fifteen-minute check-ins into meetings you already have, so there's nothing extra to schedule.", 2]], "cues": [0, 4.85, 27.23]}, "n_G8": {"dur": 28.0, "text": "This course is built from Melissa's book, Athleadership: The Elite Athletic Mindset. You don't need to read it to take part. Each lesson names the chapter if you'd like to go further, and you can order the Founder's Edition from the Athleadership website. Your Scorecard is where the season turns into results. You'll fill it in lesson by lesson and track your goals in it week by week. Download it now, and open the example to see what a finished one looks like.", "sents": [[0.11, "This course is built from Melissa's book, Athleadership: The Elite Athletic Mindset.", 0], [6.07, "You don't need to read it to take part.", 1], [8.35, "Each lesson names the chapter if you'd like to go further, and you can order the Founder's Edition from the Athleadership website.", 1], [16.05, "Your Scorecard is where the season turns into results.", 2], [19.39, "You'll fill it in lesson by lesson and track your goals in it week by week.", 2], [24.33, "Download it now, and open the example to see what a finished one looks like.", 3]], "cues": [0.11, 6.07, 16.05, 24.33]}, "n_G9": {"dur": 42.16, "text": "Every lesson follows the same steps, so you'll always know where you are. It opens with a moment of pressure you'll probably recognize. Then a quick check-in, where you notice what went on in you. Only you see what you write. Next come the core lessons, a few short videos each time. You make a call on a real situation, then run a short drill that puts you under a little pressure and asks you to respond. The practice happens in your Playbook during the week. Each lesson also brings in an Athleader Pro, with a three-minute drill of their own. A quick Pulse Check tracks how you're changing across the season, and a short knowledge check covers the main ideas before you close the lesson.", "sents": [[0.01, "Every lesson follows the same steps, so you'll always know where you are.", 0], [4.83, "It opens with a moment of pressure you'll probably recognize.", 1], [8.59, "Then a quick check-in, where you notice what went on in you.", 1], [12.61, "Only you see what you write.", 1], [14.97, "Next come the core lessons, a few short videos each time.", 2], [19.25, "You make a call on a real situation, then run a short drill that puts you under a little pressure and asks you to respond.", 2], [26.33, "The practice happens in your Playbook during the week.", 3], [29.47, "Each lesson also brings in an Athleader Pro, with a three-minute drill of their own.", 3], [34.83, "A quick Pulse Check tracks how you're changing across the season, and a short knowledge check covers the main ideas before you close the lesson.", 4]], "cues": [0.01, 4.83, 14.97, 26.33, 34.83]}, "n_G10": {"dur": 10.64, "text": "Your starting point is recorded and Lesson 1 is open. It starts with how you react under pressure, and builds your season from there. Select Open Lesson 1 when you're ready.", "sents": [[0.03, "Your starting point is recorded and Lesson 1 is open.", 0], [3.75, "It starts with how you react under pressure, and builds your season from there.", 1], [8.37, "Select Open Lesson 1 when you're ready.", 1]], "cues": [0.03, 3.75]}, "n_1_0": {"dur": 9.2, "text": "Lesson 1 is about where you start. You'll spend about forty minutes here, then twenty minutes in your Playbook during the week. Select Start lesson.", "sents": [[0.03, "Lesson 1 is about where you start.", 0], [2.73, "You'll spend about forty minutes here, then twenty minutes in your Playbook during the week.", 1], [7.57, "Select Start lesson.", 1]], "cues": [0.03, 2.73]}, "n_1_1": {"dur": 10.24, "text": "Read this moment, and picture yourself in it. You don't rise to what you know in moments like this. You fall back on what you've practiced, and that's what this season works on.", "sents": [[0.01, "Read this moment, and picture yourself in it.", 0], [3.27, "You don't rise to what you know in moments like this.", 1], [6.23, "You fall back on what you've practiced, and that's what this season works on.", 1]], "cues": [0.01, 3.27]}, "n_1_3": {"dur": 12.72, "text": "Before any coaching, take one clean read of how you react. This drill is short. Press play. Melissa will stop partway through and ask what you notice. Type your answer, and the video carries on.", "sents": [[0.01, "Before any coaching, take one clean read of how you react.", 0], [4.15, "This drill is short.", 0], [5.51, "Press play.", 1], [6.99, "Melissa will stop partway through and ask what you notice.", 1], [10.49, "Type your answer, and the video carries on.", 1]], "cues": [0.01, 5.51]}, "n_1_4": {"dur": 36.16, "text": "Here's what you'll practice in this lesson. When something you were counting on falls through, you'll catch your first reaction before you act on it. You'll notice what went through your head, and what you wanted to do. You'll learn what this season conditions: Agility, Resilience, Alignment and Wellbeing. Melissa calls them the Core 4. You'll see how your operating system fits together, with the M.V.P. Blueprint as the engine and the 90-Day Way as the loop you run. And you'll write your why, in one sentence, in your Playbook this week. The Pulse Check at the end of the lesson picks this up.", "sents": [[0.05, "Here's what you'll practice in this lesson.", 0], [2.63, "When something you were counting on falls through, you'll catch your first reaction before you act on it.", 1], [8.35, "You'll notice what went through your head, and what you wanted to do.", 1], [12.05, "You'll learn what this season conditions: Agility, Resilience, Alignment and Wellbeing.", 2], [18.03, "Melissa calls them the Core 4.", 2], [20.81, "You'll see how your operating system fits together, with the M.V.P. Blueprint as the engine and the 90-Day Way as the loop you run.", 3], [29.27, "And you'll write your why, in one sentence, in your Playbook this week.", 4], [33.53, "The Pulse Check at the end of the lesson picks this up.", 4]], "cues": [0.05, 2.63, 12.05, 20.81, 29.27]}, "n_1_7": {"dur": 13.28, "text": "Melissa mentioned your Athleader Playbook. Download it now, because every lesson uses it. It opens in a new tab. Save a copy somewhere you'll find it, and if you already saved it during setup, you're all set.", "sents": [[0.05, "Melissa mentioned your Athleader Playbook.", 0], [2.87, "Download it now, because every lesson uses it.", 0], [6.15, "It opens in a new tab.", 1], [8.13, "Save a copy somewhere you'll find it, and if you already saved it during setup, you're all set.", 1]], "cues": [0.05, 6.15]}, "n_1_8": {"dur": 11.04, "text": "Agility, Resilience, Alignment and Wellbeing are what this season conditions. Select each one to hear what changes when it's conditioned. Open all four before you move on.", "sents": [[0.03, "Agility, Resilience, Alignment and Wellbeing are what this season conditions.", 0], [5.61, "Select each one to hear what changes when it's conditioned.", 1], [9.13, "Open all four before you move on.", 1]], "cues": [0.03, 5.61]}, "n_1_8_agility": {"dur": 10.48, "text": "When agility is conditioned, you don't need certainty to move. You make the call and adjust as things change. When it isn't, you wait for certainty while everything keeps changing around you.", "sents": [[0.01, "When agility is conditioned, you don't need certainty to move.", 0], [3.61, "You make the call and adjust as things change.", 0], [6.55, "When it isn't, you wait for certainty while everything keeps changing around you.", 1]], "cues": [0.01, 6.55]}, "n_1_8_resilience": {"dur": 10.4, "text": "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play. When it isn't, one hard moment follows you into the next one.", "sents": [[0.09, "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play.", 0], [6.93, "When it isn't, one hard moment follows you into the next one.", 1]], "cues": [0.09, 6.93]}, "n_1_8_alignment": {"dur": 12.24, "text": "When alignment is conditioned, you know what matters most. You make the hard call and keep people moving in the same direction. When it isn't, everything feels urgent and people pull different ways.", "sents": [[0.01, "When alignment is conditioned, you know what matters most.", 0], [3.77, "You make the hard call and keep people moving in the same direction.", 0], [8.13, "When it isn't, everything feels urgent and people pull different ways.", 1]], "cues": [0.01, 8.13]}, "n_1_8_wellbeing": {"dur": 11.76, "text": "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises. When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", "sents": [[0, "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises.", 0], [7.29, "When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", 1]], "cues": [0, 7.29]}, "n_1_9": {"dur": 30.32, "text": "Your M.V.P. Blueprint is the engine. It's your mission, your vision and your purpose, written down. Most leaders have a purpose, but fewer than one in five can say theirs in a sentence. The 90-Day Way is the loop you run that engine in. You plan for ninety days, carry out the plan, reflect every week, then reset and start the next season. The Blueprint tells you where you're going and why it matters. The 90-Day Way is how you get a little closer to it every week.", "sents": [[0.05, "Your M.V.P. Blueprint is the engine.", 0], [2.69, "It's your mission, your vision and your purpose, written down.", 0], [6.95, "Most leaders have a purpose, but fewer than one in five can say theirs in a sentence.", 1], [12.67, "The 90-Day Way is the loop you run that engine in.", 2], [16.21, "You plan for ninety days, carry out the plan, reflect every week, then reset and start the next season.", 2], [23.21, "The Blueprint tells you where you're going and why it matters.", 3], [26.95, "The 90-Day Way is how you get a little closer to it every week.", 3]], "cues": [0.05, 6.95, 12.67, 23.21]}, "n_1_10": {"dur": 9.12, "text": "Back to Thursday at 4:40, with the plan due at six. Pick the move you'd make, and you'll hear where it leads. You can try the other one afterwards.", "sents": [[0.03, "Back to Thursday at 4:40, with the plan due at six.", 0], [4.15, "Pick the move you'd make, and you'll hear where it leads.", 1], [7.21, "You can try the other one afterwards.", 1]], "cues": [0.03, 4.15]}, "n_1_10_o0": {"dur": 11.92, "text": "Answering emails until six feels productive, and under pressure it's a normal reaction. It isn't a system, though, so tomorrow looks exactly like today. Try the other option to compare.", "sents": [[0, "Answering emails until six feels productive, and under pressure it's a normal reaction.", 0], [5.81, "It isn't a system, though, so tomorrow looks exactly like today.", 0], [10.17, "Try the other option to compare.", 0]], "cues": [0]}, "n_1_10_o1": {"dur": 13.12, "text": "Three minutes to name the one outcome that matters by six, then working back from it. That's the rep, a small move you can repeat under pressure, and it's what this season builds. The plan can still be rough at six.", "sents": [[0, "Three minutes to name the one outcome that matters by six, then working back from it.", 0], [4.97, "That's the rep, a small move you can repeat under pressure, and it's what this season builds.", 0], [11.27, "The plan can still be rough at six.", 0]], "cues": [0]}, "n_1_12": {"dur": 29.84, "text": "The real work happens in your Playbook this week, and it takes about twenty minutes. Start with your why. Picture the end of the season, name the one change you most want to have made, and write your intention in one sentence. Then rate yourself from one to five on each of the Core 4. It's your starting point, and you'll rate again in Lesson 6. Last, confirm your weekly hour and sign your commitment. Select Open your Lesson 1 pages to get started.", "sents": [[0, "The real work happens in your Playbook this week, and it takes about twenty minutes.", 0], [5.09, "Start with your why.", 1], [6.93, "Picture the end of the season, name the one change you most want to have made, and write your intention in one sentence.", 1], [14.77, "Then rate yourself from one to five on each of the Core 4.", 2], [18.61, "It's your starting point, and you'll rate again in Lesson 6.", 2], [22.29, "Last, confirm your weekly hour and sign your commitment.", 3], [26.91, "Select Open your Lesson 1 pages to get started.", 3]], "cues": [0, 5.09, 14.77, 22.29]}, "n_1_13": {"dur": 9.76, "text": "Each lesson brings in an Athleader Pro, a leader who lives one part of this work. This time it's Tracey Newell, the Change Commander. Press play to hear from her.", "sents": [[0, "Each lesson brings in an Athleader Pro, a leader who lives one part of this work.", 0], [5.05, "This time it's Tracey Newell, the Change Commander.", 1], [8.49, "Press play to hear from her.", 1]], "cues": [0, 5.05]}, "n_1_14": {"dur": 10.08, "text": "Now try Tracey's drill. It takes three minutes. Select Start the timer and work through each step as it lights up. When you've finished, tick I ran this drill.", "sents": [[0, "Now try Tracey's drill.", 0], [1.59, "It takes three minutes.", 0], [3.17, "Select Start the timer and work through each step as it lights up.", 1], [7.67, "When you've finished, tick I ran this drill.", 1]], "cues": [0, 3.17]}, "n_1_16_q0": {"dur": 8.24, "text": "A few questions to check the main ideas. First: which of these best describes conditioning? Choose one, then select Submit.", "sents": [[0.03, "A few questions to check the main ideas.", 0], [2.89, "First: which of these best describes conditioning?", 0], [6.27, "Choose one, then select Submit.", 0]], "cues": [0.03]}, "n_1_16_w0": {"dur": 7.52, "text": "Conditioning is what you fall back on under pressure, when there's no time to think. Knowledge is what you can recall when there is time.", "sents": [[0, "Conditioning is what you fall back on under pressure, when there's no time to think.", 0], [5.01, "Knowledge is what you can recall when there is time.", 0]], "cues": [0]}, "n_1_16_q1": {"dur": 3.36, "text": "In your operating system, what is the 90-Day Way?", "sents": [[0, "In your operating system, what is the 90-Day Way?", 0]], "cues": [0]}, "n_1_16_w1": {"dur": 10.0, "text": "The 90-Day Way is the loop: plan, execute, reflect and reset, every ninety days. Your M.V.P. Blueprint is the engine it runs.", "sents": [[0.0, "The 90-Day Way is the loop: plan, execute, reflect and reset, every ninety days.", 0], [7.37, "Your M.V.P. Blueprint is the engine it runs.", 0]], "cues": [0.0]}, "n_1_16_q2": {"dur": 6.24, "text": "A key supplier cancels an hour before your big meeting. Which response shows conditioned agility?", "sents": [[0, "A key supplier cancels an hour before your big meeting.", 0], [3.51, "Which response shows conditioned agility?", 0]], "cues": [0]}, "n_1_16_w2": {"dur": 6.88, "text": "When agility is conditioned, you don't need certainty to move. You decide on what you have and keep adjusting as things change.", "sents": [[0, "When agility is conditioned, you don't need certainty to move.", 0], [3.67, "You decide on what you have and keep adjusting as things change.", 0]], "cues": [0]}, "n_1_16_q3": {"dur": 7.12, "text": "Last one. Why does the course ask for your first reaction before any coaching?", "sents": [[0.11, "Last one.", 0], [1.29, "Why does the course ask for your first reaction before any coaching?", 0]], "cues": [0.11]}, "n_1_16_w3": {"dur": 5.84, "text": "Your first read is a baseline. Every later lesson measures against it, and it stays private to you.", "sents": [[0.01, "Your first read is a baseline.", 0], [2.29, "Every later lesson measures against it, and it stays private to you.", 0]], "cues": [0.01]}, "n_1_17": {"dur": 34.88, "text": "Before you go, here's what to keep from this lesson. Under pressure you fall back on what you've practiced, so this season is built on conditioning rather than more knowledge. The Core 4 are what you condition. Your M.V.P. Blueprint drives them, and the 90-Day Way is the cycle you run them in. Your why is the first rep. It's in your Playbook, and it's due this week. Select Download my answers for a Word copy of everything you wrote in this lesson. If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", "sents": [[0.01, "Before you go, here's what to keep from this lesson.", 0], [3.53, "Under pressure you fall back on what you've practiced, so this season is built on conditioning rather than more knowledge.", 1], [10.83, "The Core 4 are what you condition.", 2], [13.51, "Your M.V.P. Blueprint drives them, and the 90-Day Way is the cycle you run them in.", 2], [19.33, "Your why is the first rep.", 3], [21.59, "It's in your Playbook, and it's due this week.", 3], [24.53, "Select Download my answers for a Word copy of everything you wrote in this lesson.", 4], [29.73, "If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", 4]], "cues": [0.01, 3.53, 10.83, 19.33, 24.53]}, "n_1_18": {"dur": 10.32, "text": "That's Lesson 1 done. This week, complete your Lesson 1 Playbook drills, starting with your why. Next time, in Lesson 2, you'll start on your Inner Blueprint.", "sents": [[0, "That's Lesson 1 done.", 0], [1.73, "This week, complete your Lesson 1 Playbook drills, starting with your why.", 1], [6.75, "Next time, in Lesson 2, you'll start on your Inner Blueprint.", 1]], "cues": [0, 1.73]}, "n_2_0": {"dur": 11.84, "text": "Lesson 2 is your pre-season. You'll collect the raw material for your leadership blueprint: your values, your strengths, your energy and your own game tape. Select Start lesson.", "sents": [[0.03, "Lesson 2 is your pre-season.", 0], [2.41, "You'll collect the raw material for your leadership blueprint: your values, your strengths, your energy and your own game tape.", 1], [10.45, "Select Start lesson.", 1]], "cues": [0.03, 2.41]}, "n_2_1": {"dur": 14.32, "text": "Read this moment, and notice what it stirs up in you. When a change like this hits hard, there's usually a value underneath it that you've never named. This lesson helps you name it, along with your strengths, your energy and your own game tape.", "sents": [[0.09, "Read this moment, and notice what it stirs up in you.", 0], [3.63, "When a change like this hits hard, there's usually a value underneath it that you've never named.", 1], [9.09, "This lesson helps you name it, along with your strengths, your energy and your own game tape.", 1]], "cues": [0.09, 3.63]}, "n_2_3": {"dur": 7.28, "text": "A quick look back at Lesson 1 before you start. Choose the sentence that describes conditioning. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 1 before you start.", 0], [3.13, "Choose the sentence that describes conditioning.", 1], [5.93, "This one isn't scored.", 1]], "cues": [0, 3.13]}, "n_2_4": {"dur": 29.6, "text": "This lesson is about choosing your next move on purpose when the plan changes, checked against values you've named, so your first reaction doesn't choose for you. You'll narrow a long list down to the three to five values you'd hold even when it costs you. You'll learn to tell a strength, which gives you energy, from a skill, which can drain you. And you'll map what fuels and drains you in a real week. Then you'll read your own game tape: one high point and one setback, looked at the way a coach reviews film.", "sents": [[0.01, "This lesson is about choosing your next move on purpose when the plan changes, checked against values you've named, so your first reaction doesn't choose for you.", 0], [9.21, "You'll narrow a long list down to the three to five values you'd hold even when it costs you.", 1], [14.55, "You'll learn to tell a strength, which gives you energy, from a skill, which can drain you.", 2], [19.73, "And you'll map what fuels and drains you in a real week.", 2], [23.23, "Then you'll read your own game tape: one high point and one setback, looked at the way a coach reviews film.", 3]], "cues": [0.01, 9.21, 14.55, 23.23]}, "n_2_7": {"dur": 7.6, "text": "Your Inner Blueprint has four parts, and you'll collect all of them in your Playbook this week. Select each one to hear what to look for.", "sents": [[0.03, "Your Inner Blueprint has four parts, and you'll collect all of them in your Playbook this week.", 0], [5.43, "Select each one to hear what to look for.", 1]], "cues": [0.03, 5.43]}, "n_2_7_values": {"dur": 10.8, "text": "Values are what you'd hold on to even when it costs you something. Aim for three to five. With twenty values you have no way to choose between them, and choosing is the whole point.", "sents": [[0.03, "Values are what you'd hold on to even when it costs you something.", 0], [3.99, "Aim for three to five.", 0], [5.91, "With twenty values you have no way to choose between them, and choosing is the whole point.", 0]], "cues": [0.03]}, "n_2_7_strengths": {"dur": 8.8, "text": "A strength is something you do well that also gives you energy. If you're good at something but it drains you, that's a skill, and it's worth knowing the difference.", "sents": [[0.01, "A strength is something you do well that also gives you energy.", 0], [3.93, "If you're good at something but it drains you, that's a skill, and it's worth knowing the difference.", 0]], "cues": [0.01]}, "n_2_7_energy": {"dur": 8.88, "text": "Your energy map shows which people, tasks and places fuel you and which drain you. Use a real week from your calendar rather than an ideal one.", "sents": [[0.03, "Your energy map shows which people, tasks and places fuel you and which drain you.", 0], [5.71, "Use a real week from your calendar rather than an ideal one.", 0]], "cues": [0.03]}, "n_2_7_tape": {"dur": 8.96, "text": "Your game tape is one high point and one setback, read for patterns the way a coach reads film. You're looking for what they show about you, rather than who to blame.", "sents": [[0.05, "Your game tape is one high point and one setback, read for patterns the way a coach reads film.", 0], [6.19, "You're looking for what they show about you, rather than who to blame.", 0]], "cues": [0.05]}, "n_2_9": {"dur": 10.16, "text": "Try this one. For each statement, decide whether it describes a strength or a skill. Remember the test: a strength gives you energy back, and a skill only spends it.", "sents": [[0, "Try this one.", 0], [1.15, "For each statement, decide whether it describes a strength or a skill.", 0], [5.31, "Remember the test: a strength gives you energy back, and a skill only spends it.", 1]], "cues": [0, 5.31]}, "n_2_12": {"dur": 31.28, "text": "Melissa just shared one of her own setbacks. Here's the shape of it. Two NFL front offices turned down her idea for player development. She was frustrated, and she felt inadequate. She treated the no as feedback, kept refining the idea, and pitched it again. Three years later a franchise said yes, and that became the first Player Brand University in professional sports. What she took from those three years was what she learned while the answer was still no. Look for that in your own setback this week.", "sents": [[0.01, "Melissa just shared one of her own setbacks.", 0], [2.69, "Here's the shape of it.", 0], [4.25, "Two NFL front offices turned down her idea for player development.", 1], [8.71, "She was frustrated, and she felt inadequate.", 1], [11.69, "She treated the no as feedback, kept refining the idea, and pitched it again.", 2], [17.09, "Three years later a franchise said yes, and that became the first Player Brand University in professional sports.", 3], [24.43, "What she took from those three years was what she learned while the answer was still no.", 4], [29.23, "Look for that in your own setback this week.", 4]], "cues": [0.01, 4.25, 11.69, 17.09, 24.43]}, "n_2_13": {"dur": 8.08, "text": "Back to Monday morning. The plan's been replaced, and your message is due before the stand-up. Choose your first move, and you'll hear where it leads.", "sents": [[0.09, "Back to Monday morning.", 0], [1.67, "The plan's been replaced, and your message is due before the stand-up.", 0], [5.49, "Choose your first move, and you'll hear where it leads.", 1]], "cues": [0.09, 5.49]}, "n_2_13_o0": {"dur": 13.76, "text": "Replying straight away feels decisive. But you spend the morning arguing for something that's already gone, and your team hears the argument before they hear a plan. That costs you the one hour you had. Try the other option to compare.", "sents": [[0.01, "Replying straight away feels decisive.", 0], [2.85, "But you spend the morning arguing for something that's already gone, and your team hears the argument before they hear a plan.", 0], [9.47, "That costs you the one hour you had.", 0], [12.13, "Try the other option to compare.", 0]], "cues": [0.01]}, "n_2_13_o1": {"dur": 11.04, "text": "Naming the value the old plan protected tells you what's worth fighting for and what you can let go. Then you rebuild with the team around it, and they get a leader instead of a reaction.", "sents": [[0.09, "Naming the value the old plan protected tells you what's worth fighting for and what you can let go.", 0], [6.67, "Then you rebuild with the team around it, and they get a leader instead of a reaction.", 0]], "cues": [0.09]}, "n_2_15": {"dur": 10.64, "text": "Time for the drill. It puts you under a little pressure and asks you to respond. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.35, "It puts you under a little pressure and asks you to respond.", 0], [4.91, "Press play.", 1], [6.31, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "cues": [0.01, 4.91]}, "n_2_16": {"dur": 29.2, "text": "This week's Playbook work takes about an hour, so give it a proper block of time. Start with your values. Circle every one that fits from the list, narrow it to five, then to the three you'd hold even when it costs you. Then work through your strengths and your energy audit, using last week's calendar rather than an ideal week. Finish with your game tape: one high point and one setback, and what each one shows. Select Open your Lesson 2 pages to begin.", "sents": [[0.03, "This week's Playbook work takes about an hour, so give it a proper block of time.", 0], [4.83, "Start with your values.", 1], [6.63, "Circle every one that fits from the list, narrow it to five, then to the three you'd hold even when it costs you.", 1], [13.63, "Then work through your strengths and your energy audit, using last week's calendar rather than an ideal week.", 2], [20.43, "Finish with your game tape: one high point and one setback, and what each one shows.", 3], [26.29, "Select Open your Lesson 2 pages to begin.", 3]], "cues": [0.03, 4.83, 13.63, 20.43]}, "n_2_17": {"dur": 9.84, "text": "This lesson's Athleader Pro is Dr. Michael Mannino, the Flow Alchemist. His work sits where neuroscience meets peak performance. Press play to hear from him.", "sents": [[0.03, "This lesson's Athleader Pro is Dr. Michael Mannino, the Flow Alchemist.", 0], [5.23, "His work sits where neuroscience meets peak performance.", 0], [8.57, "Press play to hear from him.", 1]], "cues": [0.03, 8.57]}, "n_2_18": {"dur": 13.84, "text": "Michael's drill is one to run with your team, and it takes three minutes. You can run it now, or save it for your next team meeting. Select Start the timer to walk through it, then tick I ran this drill once you have.", "sents": [[0, "Michael's drill is one to run with your team, and it takes three minutes.", 0], [4.77, "You can run it now, or save it for your next team meeting.", 1], [8.37, "Select Start the timer to walk through it, then tick I ran this drill once you have.", 1]], "cues": [0, 4.77]}, "n_2_20_q0": {"dur": 11.6, "text": "A few questions to check the main ideas. You're excellent at building financial models, and everyone asks you to build them. You dread every one. In this system, what is that?", "sents": [[0.01, "A few questions to check the main ideas.", 0], [2.81, "You're excellent at building financial models, and everyone asks you to build them.", 0], [7.63, "You dread every one.", 0], [9.73, "In this system, what is that?", 0]], "cues": [0.01]}, "n_2_20_w0": {"dur": 6.64, "text": "It's a skill. You're good at it, but it takes energy instead of giving it back. A strength does both.", "sents": [[0.05, "It's a skill.", 0], [1.03, "You're good at it, but it takes energy instead of giving it back.", 0], [4.93, "A strength does both.", 0]], "cues": [0.05]}, "n_2_20_q1": {"dur": 2.08, "text": "How many core values should you aim to name?", "sents": [[0, "How many core values should you aim to name?", 0]], "cues": [0]}, "n_2_20_w1": {"dur": 5.6, "text": "Three to five. With a long list, you have no way to choose between them when it matters.", "sents": [[0, "Three to five.", 0], [1.45, "With a long list, you have no way to choose between them when it matters.", 0]], "cues": [0]}, "n_2_20_q2": {"dur": 3.92, "text": "Last one. When you review your game tape, what are you looking for?", "sents": [[0.03, "Last one.", 0], [1.27, "When you review your game tape, what are you looking for?", 0]], "cues": [0.03]}, "n_2_20_w2": {"dur": 5.44, "text": "Patterns. Read it the way a coach reads film: what you did, and what it shows about you.", "sents": [[0, "Patterns.", 0], [1.03, "Read it the way a coach reads film: what you did, and what it shows about you.", 0]], "cues": [0]}, "n_2_21": {"dur": 32.0, "text": "Before you go, a quick recap. Your values are the filter you already use without knowing it. This week, you name them. A strength gives you energy back, and a skill only spends it, so you can be excellent at something that's quietly wearing you out. And your setbacks are data. Read one the way a coach reads film, because Lesson 3 builds on it. Select Download my answers for a Word copy of what you wrote today. Chapter 8 of the book has Melissa's own story of the front offices that said no.", "sents": [[0.03, "Before you go, a quick recap.", 0], [2.61, "Your values are the filter you already use without knowing it.", 1], [6.31, "This week, you name them.", 1], [8.37, "A strength gives you energy back, and a skill only spends it, so you can be excellent at something that's quietly wearing you out.", 2], [16.05, "And your setbacks are data.", 3], [18.03, "Read one the way a coach reads film, because Lesson 3 builds on it.", 3], [22.51, "Select Download my answers for a Word copy of what you wrote today.", 4], [27.33, "Chapter 8 of the book has Melissa's own story of the front offices that said no.", 4]], "cues": [0.03, 2.61, 8.37, 16.05, 22.51]}, "n_2_22": {"dur": 9.36, "text": "That's Lesson 2 done. This week, complete your Lesson 2 Playbook drills, and give them a full hour. Next time you'll build your blueprint from what you collect.", "sents": [[0, "That's Lesson 2 done.", 0], [1.77, "This week, complete your Lesson 2 Playbook drills, and give them a full hour.", 1], [6.53, "Next time you'll build your blueprint from what you collect.", 1]], "cues": [0, 1.77]}, "n_3_0": {"dur": 8.88, "text": "Lesson 3 is where you draft your M.V.P.: your mission, your vision and your purpose. Select Start lesson.", "sents": [[0.0, "Lesson 3 is where you draft your M.V.P.: your mission, your vision and your purpose.", 0], [6.45, "Select Start lesson.", 1]], "cues": [0.0, 6.45]}, "n_3_1": {"dur": 12.4, "text": "Read this moment. Which way would you lean? Most people decide by which option is louder. This lesson gives you a tie-breaker: a purpose, a vision and a mission you've actually written down.", "sents": [[0, "Read this moment.", 0], [1.43, "Which way would you lean?", 0], [3.45, "Most people decide by which option is louder.", 1], [6.63, "This lesson gives you a tie-breaker: a purpose, a vision and a mission you've actually written down.", 1]], "cues": [0, 3.45]}, "n_3_3": {"dur": 7.2, "text": "A quick look back at Lesson 2. What makes something a strength rather than a skill? This one isn't scored.", "sents": [[0.05, "A quick look back at Lesson 2.", 0], [2.41, "What makes something a strength rather than a skill?", 1], [5.53, "This one isn't scored.", 1]], "cues": [0.05, 2.41]}, "n_3_4": {"dur": 24.08, "text": "This lesson gives you a way to choose between two good options: a purpose you've written down. You'll draft your purpose in one sentence, separate from your job title. You'll picture where you are in three to five years, in enough detail to see it, and write a mission statement from a simple template. Then you'll move all of it, with your values, into Part 1 of your 90-Day Way Scorecard.", "sents": [[0.05, "This lesson gives you a way to choose between two good options: a purpose you've written down.", 0], [6.19, "You'll draft your purpose in one sentence, separate from your job title.", 1], [10.63, "You'll picture where you are in three to five years, in enough detail to see it, and write a mission statement from a simple template.", 2], [18.47, "Then you'll move all of it, with your values, into Part 1 of your 90-Day Way Scorecard.", 3]], "cues": [0.05, 6.19, 10.63, 18.47]}, "n_3_7": {"dur": 7.28, "text": "Draft these in order, starting with purpose, because purpose is the tie-breaker. Select each one to hear how to test it.", "sents": [[0.09, "Draft these in order, starting with purpose, because purpose is the tie-breaker.", 0], [5.21, "Select each one to hear how to test it.", 1]], "cues": [0.09, 5.21]}, "n_3_7_purpose": {"dur": 8.24, "text": "Your purpose is the impact you want to have, apart from any job. Test it by asking whether it would still be true if you changed employers tomorrow.", "sents": [[0.03, "Your purpose is the impact you want to have, apart from any job.", 0], [4.11, "Test it by asking whether it would still be true if you changed employers tomorrow.", 0]], "cues": [0.03]}, "n_3_7_vision": {"dur": 8.48, "text": "Your vision is where you are in three to five years, in real detail. If you can't see it, or name who's in the room with you, keep going.", "sents": [[0.09, "Your vision is where you are in three to five years, in real detail.", 0], [4.85, "If you can't see it, or name who's in the room with you, keep going.", 0]], "cues": [0.09]}, "n_3_7_mission": {"dur": 9.36, "text": "Your mission is what you do, who it's for and what it achieves. Use the template on screen, then read it out loud and change any word that doesn't sound like you.", "sents": [[0.01, "Your mission is what you do, who it's for and what it achieves.", 0], [4.31, "Use the template on screen, then read it out loud and change any word that doesn't sound like you.", 0]], "cues": [0.01]}, "n_3_7_values": {"dur": 7.84, "text": "Your values are the guardrails you named last lesson. If you wouldn't hold one when it costs you something, it's a preference, and you can let it go.", "sents": [[0.07, "Your values are the guardrails you named last lesson.", 0], [3.35, "If you wouldn't hold one when it costs you something, it's a preference, and you can let it go.", 0]], "cues": [0.07]}, "n_3_10": {"dur": 9.84, "text": "Try sorting these. For each statement, decide whether it's a purpose, a vision or a mission. A tip: the mission is the one with an action in it.", "sents": [[0, "Try sorting these.", 0], [1.61, "For each statement, decide whether it's a purpose, a vision or a mission.", 0], [6.73, "A tip: the mission is the one with an action in it.", 1]], "cues": [0, 6.73]}, "n_3_12": {"dur": 30.08, "text": "A year is too long to plan in detail, and a week is too short to build momentum. Ninety days is long enough to finish something real. Each season runs the same loop. You plan two or three goals tied to your M.V.P., act on them daily and weekly, check in every week, then reset. Your Scorecard holds the whole season. You fill in Part 1 this week, your game plan in Lesson 5, and the assessment and reset in Lesson 6. Open it this week and have a look.", "sents": [[0.01, "A year is too long to plan in detail, and a week is too short to build momentum.", 0], [5.09, "Ninety days is long enough to finish something real.", 0], [8.53, "Each season runs the same loop.", 1], [10.79, "You plan two or three goals tied to your M.V.P., act on them daily and weekly, check in every week, then reset.", 1], [18.55, "Your Scorecard holds the whole season.", 2], [21.23, "You fill in Part 1 this week, your game plan in Lesson 5, and the assessment and reset in Lesson 6.", 2], [28.39, "Open it this week and have a look.", 2]], "cues": [0.01, 8.53, 18.55]}, "n_3_13": {"dur": 6.32, "text": "Back to those two opportunities in the same week. Pick the question you'd ask yourself, and you'll hear where it leads.", "sents": [[0.07, "Back to those two opportunities in the same week.", 0], [3.17, "Pick the question you'd ask yourself, and you'll hear where it leads.", 1]], "cues": [0.07, 3.17]}, "n_3_13_o0": {"dur": 8.96, "text": "It's a fair question, but it's about managing your career. It won't tell you which opportunity is actually yours. Try the other option to compare.", "sents": [[0.07, "It's a fair question, but it's about managing your career.", 0], [3.83, "It won't tell you which opportunity is actually yours.", 0], [7.19, "Try the other option to compare.", 0]], "cues": [0.07]}, "n_3_13_o1": {"dur": 8.72, "text": "That's the tie-breaker. If neither breaks a value, pick the one that's closer to your vision. If one does break a value, you already know your answer.", "sents": [[0.07, "That's the tie-breaker.", 0], [1.63, "If neither breaks a value, pick the one that's closer to your vision.", 0], [5.63, "If one does break a value, you already know your answer.", 0]], "cues": [0.07]}, "n_3_15": {"dur": 14.96, "text": "Time for the drill. This one tests how much certainty you need before you move. Press play. Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision. Answer each time, and the video carries on.", "sents": [[0.05, "Time for the drill.", 0], [1.53, "This one tests how much certainty you need before you move.", 0], [4.85, "Press play.", 1], [6.35, "Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision.", 1], [12.49, "Answer each time, and the video carries on.", 1]], "cues": [0.05, 4.85]}, "n_3_16": {"dur": 26.56, "text": "This week's Playbook work takes a little over an hour. Draft your purpose first, using your Lesson 2 notes. It only has to be true, so don't wait for perfect. Then write your vision as if it's already happened, and fill in the mission template. Read it out loud, and change any word that doesn't sound like you. Last, move all of it, with your values, into Part 1 of your Scorecard. Both files are on this screen.", "sents": [[0.03, "This week's Playbook work takes a little over an hour.", 0], [3.45, "Draft your purpose first, using your Lesson 2 notes.", 1], [7.03, "It only has to be true, so don't wait for perfect.", 1], [10.43, "Then write your vision as if it's already happened, and fill in the mission template.", 2], [15.59, "Read it out loud, and change any word that doesn't sound like you.", 2], [19.71, "Last, move all of it, with your values, into Part 1 of your Scorecard.", 3], [24.91, "Both files are on this screen.", 3]], "cues": [0.03, 3.45, 10.43, 19.71]}, "n_3_17": {"dur": 10.32, "text": "This lesson's Athleader Pro is LaChina Robinson, the Pressure Player. She's a broadcaster who performs live, under pressure, for a living. Press play to hear from her.", "sents": [[0.05, "This lesson's Athleader Pro is LaChina Robinson, the Pressure Player.", 0], [4.91, "She's a broadcaster who performs live, under pressure, for a living.", 0], [9.11, "Press play to hear from her.", 1]], "cues": [0.05, 9.11]}, "n_3_18": {"dur": 13.28, "text": "LaChina's drill trains agility under pressure, and it takes three minutes. Think of a challenge you're facing right now, select Start the timer, and work through each step. Tick I ran this drill when you're done.", "sents": [[0.05, "LaChina's drill trains agility under pressure, and it takes three minutes.", 0], [5.45, "Think of a challenge you're facing right now, select Start the timer, and work through each step.", 1], [11.15, "Tick I ran this drill when you're done.", 1]], "cues": [0.05, 5.45]}, "n_3_20_q0": {"dur": 5.2, "text": "A few questions to check the main ideas. Which of these is a mission statement?", "sents": [[0, "A few questions to check the main ideas.", 0], [3.17, "Which of these is a mission statement?", 0]], "cues": [0]}, "n_3_20_w0": {"dur": 10.72, "text": "It follows the mission template: an action, who it's for, and what it achieves. The first is a vision, the third is a purpose, and the last is a list of values.", "sents": [[0, "It follows the mission template: an action, who it's for, and what it achieves.", 0], [5.75, "The first is a vision, the third is a purpose, and the last is a list of values.", 0]], "cues": [0]}, "n_3_20_q1": {"dur": 1.92, "text": "Why do you draft your purpose first?", "sents": [[0.09, "Why do you draft your purpose first?", 0]], "cues": [0.09]}, "n_3_20_w1": {"dur": 5.6, "text": "Purpose is the tie-breaker. When two good options compete, it tells you which one is yours.", "sents": [[0.03, "Purpose is the tie-breaker.", 0], [2.17, "When two good options compete, it tells you which one is yours.", 0]], "cues": [0.03]}, "n_3_20_q2": {"dur": 8.96, "text": "Last one. Your purpose is to champion emerging talent, and you're offered a high-profile solo project. What does your purpose suggest?", "sents": [[0.03, "Last one.", 0], [1.25, "Your purpose is to champion emerging talent, and you're offered a high-profile solo project.", 0], [7.47, "What does your purpose suggest?", 0]], "cues": [0.03]}, "n_3_20_w2": {"dur": 7.36, "text": "Your purpose points to a better yes: a way the work can grow someone else. You'll see this exact story in Lesson 4.", "sents": [[0, "Your purpose points to a better yes: a way the work can grow someone else.", 0], [5.05, "You'll see this exact story in Lesson 4.", 0]], "cues": [0]}, "n_3_21": {"dur": 29.04, "text": "Before you go, a quick recap. Your purpose is the tie-breaker. It sits apart from your job title, and when two good options collide, it tells you which one is yours. Your vision is a picture, and your mission is a sentence you can act on tonight. And ninety days is the unit of progress: plan, execute, reflect and reset, with your Scorecard holding the season. Select Download my answers for a Word copy of what you wrote today.", "sents": [[0, "Before you go, a quick recap.", 0], [2.51, "Your purpose is the tie-breaker.", 1], [4.79, "It sits apart from your job title, and when two good options collide, it tells you which one is yours.", 1], [11.35, "Your vision is a picture, and your mission is a sentence you can act on tonight.", 2], [16.29, "And ninety days is the unit of progress: plan, execute, reflect and reset, with your Scorecard holding the season.", 3], [25.21, "Select Download my answers for a Word copy of what you wrote today.", 4]], "cues": [0, 2.51, 11.35, 16.29, 25.21]}, "n_3_22": {"dur": 12.32, "text": "That's Lesson 3 done. This week, complete your Lesson 3 Playbook drills and Part 1 of your Scorecard, and read your statements out loud every few days. Next time, you'll put your blueprint under pressure.", "sents": [[0.05, "That's Lesson 3 done.", 0], [1.85, "This week, complete your Lesson 3 Playbook drills and Part 1 of your Scorecard, and read your statements out loud every few days.", 1], [9.81, "Next time, you'll put your blueprint under pressure.", 1]], "cues": [0.05, 1.85]}, "n_4_0": {"dur": 8.72, "text": "Lesson 4 puts your M.V.P. to work, as a filter for decisions and as your answer when you meet resistance. Select Start lesson.", "sents": [[0.09, "Lesson 4 puts your M.V.P. to work, as a filter for decisions and as your answer when you meet resistance.", 0], [6.97, "Select Start lesson.", 1]], "cues": [0.09, 6.97]}, "n_4_1": {"dur": 10.88, "text": "Read this moment. What would you say in the next five seconds? That answer is where resilience shows up. This lesson gives you two moves for that moment, and one for the week before it.", "sents": [[0.01, "Read this moment.", 0], [1.37, "What would you say in the next five seconds?", 0], [3.95, "That answer is where resilience shows up.", 1], [6.85, "This lesson gives you two moves for that moment, and one for the week before it.", 1]], "cues": [0.01, 3.95]}, "n_4_3": {"dur": 7.44, "text": "A quick look back at Lesson 3. What is your purpose statement for, day to day? This one isn't scored.", "sents": [[0.03, "A quick look back at Lesson 3.", 0], [2.59, "What is your purpose statement for, day to day?", 1], [5.83, "This one isn't scored.", 1]], "cues": [0.03, 2.59]}, "n_4_4": {"dur": 26.08, "text": "This lesson is about answering a real request with a better yes or a clear no, using the purpose and mission you wrote last week. You'll run a decision through a four-question filter. You'll name the sentence your inner critic repeats and answer it from your purpose. And you'll turn one outside 'no' into a question that makes your idea stronger. Then you'll find the weak point in each of your ninety-day goals, and plan the pivot while you're calm.", "sents": [[0.01, "This lesson is about answering a real request with a better yes or a clear no, using the purpose and mission you wrote last week.", 0], [8.47, "You'll run a decision through a four-question filter.", 1], [11.41, "You'll name the sentence your inner critic repeats and answer it from your purpose.", 2], [16.07, "And you'll turn one outside 'no' into a question that makes your idea stronger.", 2], [20.85, "Then you'll find the weak point in each of your ninety-day goals, and plan the pivot while you're calm.", 3]], "cues": [0.01, 8.47, 11.41, 20.85]}, "n_4_7": {"dur": 34.16, "text": "Here's the filter Melissa just walked through. Ask the questions in order, and stop at the first no. First, does it fit your purpose? If it doesn't, it's a distraction, however good it looks. Second, does it move your mission forward: the action, audience, focus and result you wrote last lesson? Third, does it break one of your values? One broken value outweighs nine good reasons. And last, is there a better yes? Ask who else could grow if you say no, and what you could offer instead.", "sents": [[0.01, "Here's the filter Melissa just walked through.", 0], [2.79, "Ask the questions in order, and stop at the first no.", 0], [6.59, "First, does it fit your purpose?", 1], [9.23, "If it doesn't, it's a distraction, however good it looks.", 1], [13.25, "Second, does it move your mission forward: the action, audience, focus and result you wrote last lesson?", 2], [20.75, "Third, does it break one of your values?", 3], [23.83, "One broken value outweighs nine good reasons.", 3], [27.17, "And last, is there a better yes?", 4], [30.21, "Ask who else could grow if you say no, and what you could offer instead.", 4]], "cues": [0.01, 6.59, 13.25, 20.75, 27.17]}, "n_4_8": {"dur": 36.16, "text": "Let's look at the shape of Anna's story. Anna's purpose is to champion emerging talent. Her boss offers her a high-profile data project that she'd work on alone, for a full quarter. She runs it through the filter. It doesn't fit her purpose or her mission, so she proposes a better yes: her rising analyst, David, takes the project, and she oversees it. The project gets done, David grows, and her boss sees her thinking strategically. She never actually said no. The filter doesn't make you say no. It gives your yes and your no a reason you can explain.", "sents": [[0.01, "Let's look at the shape of Anna's story.", 0], [2.81, "Anna's purpose is to champion emerging talent.", 1], [6.25, "Her boss offers her a high-profile data project that she'd work on alone, for a full quarter.", 1], [12.35, "She runs it through the filter.", 2], [14.31, "It doesn't fit her purpose or her mission, so she proposes a better yes: her rising analyst, David, takes the project, and she oversees it.", 2], [23.27, "The project gets done, David grows, and her boss sees her thinking strategically.", 3], [28.63, "She never actually said no.", 3], [30.81, "The filter doesn't make you say no.", 4], [33.09, "It gives your yes and your no a reason you can explain.", 4]], "cues": [0.01, 2.81, 12.35, 23.27, 30.81]}, "n_4_10": {"dur": 24.64, "text": "Resistance comes from two places, and each one needs a different move. Internal resistance is your inner critic. Name the exact sentence it says and answer it once, in writing, from your purpose. External resistance comes from other people or thin resources. Treat their no as not yet, and ask what the last attempt taught. Sort these into internal and external.", "sents": [[0.01, "Resistance comes from two places, and each one needs a different move.", 0], [4.87, "Internal resistance is your inner critic.", 1], [7.53, "Name the exact sentence it says and answer it once, in writing, from your purpose.", 1], [12.95, "External resistance comes from other people or thin resources.", 1], [17.15, "Treat their no as not yet, and ask what the last attempt taught.", 1], [22.11, "Sort these into internal and external.", 2]], "cues": [0.01, 4.87, 22.11]}, "n_4_12": {"dur": 5.52, "text": "Back to the room, where everyone is looking at you. Choose what you'd say, and you'll hear where it leads.", "sents": [[0.01, "Back to the room, where everyone is looking at you.", 0], [2.99, "Choose what you'd say, and you'll hear where it leads.", 1]], "cues": [0.01, 2.99]}, "n_4_12_o0": {"dur": 9.76, "text": "That's polite, and it's a missed chance. You've accepted the no as a verdict, and you've learned nothing about why the last attempt failed. Try the other option to compare.", "sents": [[0.05, "That's polite, and it's a missed chance.", 0], [2.65, "You've accepted the no as a verdict, and you've learned nothing about why the last attempt failed.", 0], [8.11, "Try the other option to compare.", 0]], "cues": [0.05]}, "n_4_12_o1": {"dur": 7.28, "text": "That's the reframe. You've turned a shutdown into a question that gathers data, and you've made the skeptic part of the solution.", "sents": [[0.05, "That's the reframe.", 0], [1.75, "You've turned a shutdown into a question that gathers data, and you've made the skeptic part of the solution.", 0]], "cues": [0.05]}, "n_4_14": {"dur": 11.6, "text": "Time for the drill. This one is about how quickly you recover when something goes wrong. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0.03, "Time for the drill.", 0], [1.61, "This one is about how quickly you recover when something goes wrong.", 0], [5.57, "Press play.", 1], [7.11, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "cues": [0.03, 5.57]}, "n_4_15": {"dur": 29.52, "text": "This week's Playbook work takes just under an hour. Work the scenario through the four filter questions, then do the same with one real request from your week. Write down the exact sentence your inner critic says, and your answer to it. Then take one real no from the last month and rewrite it as not yet, with the question you'll ask. Last, find where each of your ninety-day goals is most likely to break, and write the pivot. Select Open your Lesson 4 pages to begin.", "sents": [[0.03, "This week's Playbook work takes just under an hour.", 0], [3.45, "Work the scenario through the four filter questions, then do the same with one real request from your week.", 1], [9.91, "Write down the exact sentence your inner critic says, and your answer to it.", 2], [14.41, "Then take one real no from the last month and rewrite it as not yet, with the question you'll ask.", 2], [20.93, "Last, find where each of your ninety-day goals is most likely to break, and write the pivot.", 3], [26.95, "Select Open your Lesson 4 pages to begin.", 3]], "cues": [0.03, 3.45, 9.91, 20.93]}, "n_4_16": {"dur": 10.88, "text": "This lesson's Athleader Pro is Sagar Pandya, the AI Integrator. He helps leaders keep people and technology pulling in the same direction. Press play to hear from him.", "sents": [[0.03, "This lesson's Athleader Pro is Sagar Pandya, the AI Integrator.", 0], [5.17, "He helps leaders keep people and technology pulling in the same direction.", 0], [9.53, "Press play to hear from him.", 1]], "cues": [0.03, 9.53]}, "n_4_17": {"dur": 14.64, "text": "Sagar's drill is a fifteen-minute exercise to run with your team, to get everyone aligned on one mission. Save it for your next team meeting, or select Start the timer to see how it runs. Tick I ran this drill once you have.", "sents": [[0.03, "Sagar's drill is a fifteen-minute exercise to run with your team, to get everyone aligned on one mission.", 0], [6.77, "Save it for your next team meeting, or select Start the timer to see how it runs.", 1], [11.63, "Tick I ran this drill once you have.", 1]], "cues": [0.03, 6.77]}, "n_4_19_q0": {"dur": 6.56, "text": "A few questions to check the main ideas. In the decision filter, when do you stop asking questions?", "sents": [[0.01, "A few questions to check the main ideas.", 0], [3.17, "In the decision filter, when do you stop asking questions?", 0]], "cues": [0.01]}, "n_4_19_w0": {"dur": 7.2, "text": "Stop at the first no. Then look for the better yes: who else could grow, and what you could offer instead.", "sents": [[0, "Stop at the first no.", 0], [1.73, "Then look for the better yes: who else could grow, and what you could offer instead.", 0]], "cues": [0]}, "n_4_19_q1": {"dur": 5.76, "text": "Your inner critic says, you're not ready for this. What's the conditioned response?", "sents": [[0.03, "Your inner critic says, you're not ready for this.", 0], [3.79, "What's the conditioned response?", 0]], "cues": [0.03]}, "n_4_19_w1": {"dur": 7.12, "text": "Name the exact sentence and answer it once, in writing, from your purpose. You don't argue with it, and you don't obey it.", "sents": [[0.01, "Name the exact sentence and answer it once, in writing, from your purpose.", 0], [4.83, "You don't argue with it, and you don't obey it.", 0]], "cues": [0.01]}, "n_4_19_q2": {"dur": 7.44, "text": "Last one. Your ninety-day goal depends on one supplier delivering in week six. What does stress-testing that goal mean?", "sents": [[0.03, "Last one.", 0], [1.19, "Your ninety-day goal depends on one supplier delivering in week six.", 0], [5.51, "What does stress-testing that goal mean?", 0]], "cues": [0.03]}, "n_4_19_w2": {"dur": 5.6, "text": "Agility is planned ahead. You find the weak link now, and decide the pivot while you're calm.", "sents": [[0.01, "Agility is planned ahead.", 0], [2.41, "You find the weak link now, and decide the pivot while you're calm.", 0]], "cues": [0.01]}, "n_4_20": {"dur": 31.44, "text": "Before you go, a quick recap. The filter gives your yes and your no a reason. Check purpose, mission and values, then look for the better yes. Resistance comes in two kinds. Name your inner critic and answer it once. Treat an outside no as not yet, and ask a question. And agility is planned before it's needed. Find the weak link in each goal now, and decide the pivot while you're calm. Select Download my answers for a Word copy of what you wrote today.", "sents": [[0.01, "Before you go, a quick recap.", 0], [2.61, "The filter gives your yes and your no a reason.", 1], [5.61, "Check purpose, mission and values, then look for the better yes.", 1], [10.31, "Resistance comes in two kinds.", 2], [12.57, "Name your inner critic and answer it once.", 2], [15.43, "Treat an outside no as not yet, and ask a question.", 2], [19.45, "And agility is planned before it's needed.", 3], [22.29, "Find the weak link in each goal now, and decide the pivot while you're calm.", 3], [27.35, "Select Download my answers for a Word copy of what you wrote today.", 4]], "cues": [0.01, 2.61, 10.31, 19.45, 27.35]}, "n_4_21": {"dur": 10.4, "text": "That's Lesson 4 done. This week, complete your Lesson 4 Playbook drills, and use the filter on one real request. Next time, you'll build your ninety-day plan.", "sents": [[0.05, "That's Lesson 4 done.", 0], [1.87, "This week, complete your Lesson 4 Playbook drills, and use the filter on one real request.", 1], [7.87, "Next time, you'll build your ninety-day plan.", 1]], "cues": [0.05, 1.87]}, "n_5_0": {"dur": 5.92, "text": "Lesson 5 turns your goals into a plan with names and dates on it. Select Start lesson.", "sents": [[0.07, "Lesson 5 turns your goals into a plan with names and dates on it.", 0], [4.31, "Select Start lesson.", 1]], "cues": [0.07, 4.31]}, "n_5_1": {"dur": 9.28, "text": "Read this moment. Does it sound familiar? A goal you can't start on Monday morning isn't ready yet. This lesson turns wishes into work you can start.", "sents": [[0.07, "Read this moment.", 0], [1.49, "Does it sound familiar?", 0], [3.11, "A goal you can't start on Monday morning isn't ready yet.", 1], [6.67, "This lesson turns wishes into work you can start.", 1]], "cues": [0.07, 3.11]}, "n_5_3": {"dur": 6.56, "text": "A quick look back at Lesson 4. What does stress-testing a goal mean? This one isn't scored.", "sents": [[0.07, "A quick look back at Lesson 4.", 0], [2.43, "What does stress-testing a goal mean?", 1], [4.79, "This one isn't scored.", 1]], "cues": [0.07, 2.43]}, "n_5_4": {"dur": 21.12, "text": "This lesson is about writing goals you can start on Monday. You'll list what your vision needs from you, and from the people around you. You'll find the two or three gaps that matter most, and write each one as a SMART goal. Then you'll build the plan in Part 3 of your Scorecard, with actions, resources, a support team and a deadline for every goal.", "sents": [[0.05, "This lesson is about writing goals you can start on Monday.", 0], [3.67, "You'll list what your vision needs from you, and from the people around you.", 1], [7.73, "You'll find the two or three gaps that matter most, and write each one as a SMART goal.", 2], [13.17, "Then you'll build the plan in Part 3 of your Scorecard, with actions, resources, a support team and a deadline for every goal.", 3]], "cues": [0.05, 3.67, 7.73, 13.17]}, "n_5_7": {"dur": 33.84, "text": "Every plan needs two things in place, and most people only check the first. Personal readiness is your own state: whether you believe it's achievable, whether you have the energy for it, and which skills are missing. Lynn had the legal experience. Her gaps were managing people, managing budgets and keeping up with her industry. Relational alignment is how you're set up with others: your manager, your peers, your team and the people at home. Lynn's plan only worked once her spouse, her boss and her team were all pulling the same way.", "sents": [[0, "Every plan needs two things in place, and most people only check the first.", 0], [4.99, "Personal readiness is your own state: whether you believe it's achievable, whether you have the energy for it, and which skills are missing.", 1], [13.29, "Lynn had the legal experience.", 1], [15.47, "Her gaps were managing people, managing budgets and keeping up with her industry.", 1], [20.99, "Relational alignment is how you're set up with others: your manager, your peers, your team and the people at home.", 2], [28.65, "Lynn's plan only worked once her spouse, her boss and her team were all pulling the same way.", 2]], "cues": [0, 4.99, 20.99]}, "n_5_9": {"dur": 28.56, "text": "Here's Evan's goal from the video, built one letter at a time. It's specific: partnership proposals from qualified vendors. And it's measurable, because three proposals is something he can count. It's attainable, since sixty days is enough to run a small selection process. And it's relevant, because a technical partner is exactly what his online community needs. And it's time-bound: within sixty days. A goal like this tells you what to do on Monday.", "sents": [[0.05, "Here's Evan's goal from the video, built one letter at a time.", 0], [4.23, "It's specific: partnership proposals from qualified vendors.", 1], [8.37, "And it's measurable, because three proposals is something he can count.", 1], [12.85, "It's attainable, since sixty days is enough to run a small selection process.", 2], [17.61, "And it's relevant, because a technical partner is exactly what his online community needs.", 2], [23.23, "And it's time-bound: within sixty days.", 3], [26.35, "A goal like this tells you what to do on Monday.", 3]], "cues": [0.05, 4.23, 12.85, 23.23]}, "n_5_11": {"dur": 29.6, "text": "Every goal in Part 3 of your Scorecard answers these questions. Actions are the concrete steps you'll take every day or week. Resources are what you need: time, money, an introduction, or one piece of information. Your corner is who's supporting you, at work and at home, and how often you'll check in with them. Set that rhythm now. And every goal gets a deadline and a celebration. The date drives the work, and the celebration makes you want the next one.", "sents": [[0.01, "Every goal in Part 3 of your Scorecard answers these questions.", 0], [4.23, "Actions are the concrete steps you'll take every day or week.", 1], [8.21, "Resources are what you need: time, money, an introduction, or one piece of information.", 1], [14.61, "Your corner is who's supporting you, at work and at home, and how often you'll check in with them.", 2], [20.57, "Set that rhythm now.", 2], [22.31, "And every goal gets a deadline and a celebration.", 3], [25.81, "The date drives the work, and the celebration makes you want the next one.", 3]], "cues": [0.01, 4.23, 14.61, 22.31]}, "n_5_12": {"dur": 7.52, "text": "Back to that budget goal from the start of the lesson. Here's a similar gap. Choose the version you could start on Monday, and you'll hear why.", "sents": [[0.09, "Back to that budget goal from the start of the lesson.", 0], [2.85, "Here's a similar gap.", 0], [4.51, "Choose the version you could start on Monday, and you'll hear why.", 1]], "cues": [0.09, 4.51]}, "n_5_12_o0": {"dur": 7.92, "text": "That's a wish. There's nothing to do on Monday morning, and no way to know when you're done. Try the other option to compare.", "sents": [[0.03, "That's a wish.", 0], [1.23, "There's nothing to do on Monday morning, and no way to know when you're done.", 0], [5.57, "Try the other option to compare.", 0]], "cues": [0.03]}, "n_5_12_o1": {"dur": 6.88, "text": "That's a SMART goal, and it builds alignment with your manager at the same time. You know exactly what Monday looks like.", "sents": [[0.11, "That's a SMART goal, and it builds alignment with your manager at the same time.", 0], [4.85, "You know exactly what Monday looks like.", 0]], "cues": [0.11]}, "n_5_14": {"dur": 10.8, "text": "Time for the drill. This one puts you in a disagreement, in front of other people. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0, "Time for the drill.", 0], [1.61, "This one puts you in a disagreement, in front of other people.", 0], [5.33, "Press play.", 1], [6.71, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "cues": [0, 5.33]}, "n_5_15": {"dur": 28.32, "text": "This is the biggest Playbook week of the season, about ninety minutes, and it's the most useful one. List everything your vision needs, from you and from the people around you. Don't judge it yet. Rate yourself against that list, pick the two or three gaps that matter most, and write each one as a SMART goal. Then build your plan in Part 3 of your Scorecard, and start the weekly check-in in Part 4. Fifteen minutes every week from now on.", "sents": [[0.05, "This is the biggest Playbook week of the season, about ninety minutes, and it's the most useful one.", 0], [6.29, "List everything your vision needs, from you and from the people around you.", 1], [11.09, "Don't judge it yet.", 1], [12.65, "Rate yourself against that list, pick the two or three gaps that matter most, and write each one as a SMART goal.", 2], [19.97, "Then build your plan in Part 3 of your Scorecard, and start the weekly check-in in Part 4.", 3], [26.17, "Fifteen minutes every week from now on.", 3]], "cues": [0.05, 6.29, 12.65, 19.97]}, "n_5_16": {"dur": 12.72, "text": "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst. She's an IFBB Pro, and her story is about what peak performance costs when there's nothing underneath it. Press play to hear from her.", "sents": [[0.01, "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst.", 0], [4.75, "She's an IFBB Pro, and her story is about what peak performance costs when there's nothing underneath it.", 0], [11.45, "Press play to hear from her.", 1]], "cues": [0.01, 11.45]}, "n_5_17": {"dur": 11.44, "text": "Ryall's drill is an energy audit, and it takes three minutes. Select Start the timer and work through each step as it lights up. Tick I ran this drill when you're done.", "sents": [[0.01, "Ryall's drill is an energy audit, and it takes three minutes.", 0], [4.37, "Select Start the timer and work through each step as it lights up.", 1], [9.15, "Tick I ran this drill when you're done.", 1]], "cues": [0.01, 4.37]}, "n_5_19_q0": {"dur": 7.6, "text": "A few questions to check the main ideas. Which part of a SMART goal is missing from: get three mentors to review my plan?", "sents": [[0.03, "A few questions to check the main ideas.", 0], [2.97, "Which part of a SMART goal is missing from: get three mentors to review my plan?", 0]], "cues": [0.03]}, "n_5_19_w0": {"dur": 7.12, "text": "It's time-bound. Three mentors is specific and measurable, but without a date it never becomes urgent.", "sents": [[0.01, "It's time-bound.", 0], [1.43, "Three mentors is specific and measurable, but without a date it never becomes urgent.", 0]], "cues": [0.01]}, "n_5_19_q1": {"dur": 1.44, "text": "What made Lynn's plan hold?", "sents": [[0.07, "What made Lynn's plan hold?", 0]], "cues": [0.07]}, "n_5_19_w1": {"dur": 6.48, "text": "Her home, her boss and her team were all aligned with the plan. Personal readiness was only half of it.", "sents": [[0.03, "Her home, her boss and her team were all aligned with the plan.", 0], [4.39, "Personal readiness was only half of it.", 0]], "cues": [0.03]}, "n_5_19_q2": {"dur": 4.0, "text": "Last one. Which question does every goal in your Scorecard answer?", "sents": [[0, "Last one.", 0], [1.23, "Which question does every goal in your Scorecard answer?", 0]], "cues": [0]}, "n_5_19_w2": {"dur": 6.56, "text": "Every goal names who's in your corner and how often you'll check in, along with actions, resources and a deadline.", "sents": [[0.01, "Every goal names who's in your corner and how often you'll check in, along with actions, resources and a deadline.", 0]], "cues": [0.01]}, "n_5_20": {"dur": 34.72, "text": "Before you go, a quick recap. Readiness has two halves: your own mindset, energy and skills, and your alignment with your manager, your peers, your team and home. A goal you can't start on Monday isn't ready. Make it specific, measurable, attainable, relevant and time-bound. And every goal answers four questions: actions, resources, your corner, and a deadline with a celebration. That's Part 3 of your Scorecard. Select Download my answers for a Word copy of what you wrote today.", "sents": [[0.05, "Before you go, a quick recap.", 0], [2.41, "Readiness has two halves: your own mindset, energy and skills, and your alignment with your manager, your peers, your team and home.", 1], [11.81, "A goal you can't start on Monday isn't ready.", 2], [14.69, "Make it specific, measurable, attainable, relevant and time-bound.", 2], [20.07, "And every goal answers four questions: actions, resources, your corner, and a deadline with a celebration.", 3], [28.43, "That's Part 3 of your Scorecard.", 3], [30.81, "Select Download my answers for a Word copy of what you wrote today.", 4]], "cues": [0.05, 2.41, 11.81, 20.07, 30.81]}, "n_5_21": {"dur": 9.6, "text": "That's Lesson 5 done. This week, complete your Lesson 5 Playbook drills and build your ninety-day plan in your Scorecard. Next time is the victory lap.", "sents": [[0.09, "That's Lesson 5 done.", 0], [1.83, "This week, complete your Lesson 5 Playbook drills and build your ninety-day plan in your Scorecard.", 1], [7.77, "Next time is the victory lap.", 1]], "cues": [0.09, 1.83]}, "n_6_0": {"dur": 9.04, "text": "Lesson 6 is your victory lap. You'll look back at the season, see what changed, and set up the next ninety days. Select Start lesson.", "sents": [[0.07, "Lesson 6 is your victory lap.", 0], [2.49, "You'll look back at the season, see what changed, and set up the next ninety days.", 1], [7.47, "Select Start lesson.", 1]], "cues": [0.07, 2.49]}, "n_6_1": {"dur": 7.52, "text": "Read this moment. You're about to look. The point is to see what changed, and to decide what the next ninety days are for.", "sents": [[0.05, "Read this moment.", 0], [1.43, "You're about to look.", 1], [3.01, "The point is to see what changed, and to decide what the next ninety days are for.", 1]], "cues": [0.05, 1.43]}, "n_6_3": {"dur": 8.0, "text": "A quick look back at Lesson 5. How many questions does every goal answer in your Scorecard? This one isn't scored.", "sents": [[0.05, "A quick look back at Lesson 5.", 0], [2.71, "How many questions does every goal answer in your Scorecard?", 1], [6.79, "This one isn't scored.", 1]], "cues": [0.05, 2.71]}, "n_6_4": {"dur": 22.48, "text": "This lesson is about seeing what changed and setting up the next season. You'll name one specific win for each of the Core 4. You'll rate yourself again, next to your Lesson 1 baseline, and choose one habit per pillar to keep and one thing to stop. Then you'll close the season in Part 6 of your Scorecard, and pick the pillar you'll focus on for the next ninety days.", "sents": [[0.07, "This lesson is about seeing what changed and setting up the next season.", 0], [4.65, "You'll name one specific win for each of the Core 4.", 1], [8.49, "You'll rate yourself again, next to your Lesson 1 baseline, and choose one habit per pillar to keep and one thing to stop.", 2], [15.99, "Then you'll close the season in Part 6 of your Scorecard, and pick the pillar you'll focus on for the next ninety days.", 3]], "cues": [0.07, 4.65, 8.49, 15.99]}, "n_6_7": {"dur": 11.52, "text": "Here's one question for each pillar. Answer each with a specific moment from this season, because a named moment tells you which strategy worked. If you get stuck on one, select Need a prompt.", "sents": [[0.09, "Here's one question for each pillar.", 0], [2.35, "Answer each with a specific moment from this season, because a named moment tells you which strategy worked.", 0], [8.73, "If you get stuck on one, select Need a prompt.", 1]], "cues": [0.09, 8.73]}, "n_6_9": {"dur": 13.04, "text": "Now put your Lesson 1 baseline next to today. Enter the ratings you gave yourself in Drill 1.2, read the intention you wrote, then rate yourself again on the same four. The movement matters more than the number.", "sents": [[0.05, "Now put your Lesson 1 baseline next to today.", 0], [3.17, "Enter the ratings you gave yourself in Drill 1.2, read the intention you wrote, then rate yourself again on the same four.", 1], [11.05, "The movement matters more than the number.", 1]], "cues": [0.05, 3.17]}, "n_6_11": {"dur": 8.24, "text": "One season ends, and the next one begins with the same four steps. Select each step to see what it looks like for your next season.", "sents": [[0.03, "One season ends, and the next one begins with the same four steps.", 0], [4.67, "Select each step to see what it looks like for your next season.", 1]], "cues": [0.03, 4.67]}, "n_6_12": {"dur": 7.2, "text": "The season's over and your motivation is high. Choose the move that makes next season happen, and you'll hear where it leads.", "sents": [[0.05, "The season's over and your motivation is high.", 0], [3.21, "Choose the move that makes next season happen, and you'll hear where it leads.", 1]], "cues": [0.05, 3.21]}, "n_6_12_o0": {"dur": 9.44, "text": "Momentum without a plan is how the Playbook ends up on a shelf. You'd get about two weeks of energy, then the old habits come back. Try the other option to compare.", "sents": [[0.01, "Momentum without a plan is how the Playbook ends up on a shelf.", 0], [3.93, "You'd get about two weeks of energy, then the old habits come back.", 0], [7.77, "Try the other option to compare.", 0]], "cues": [0.01]}, "n_6_12_o1": {"dur": 6.24, "text": "That's the system doing the work, instead of your motivation. The loop keeps running because it's in the calendar.", "sents": [[0.05, "That's the system doing the work, instead of your motivation.", 0], [3.71, "The loop keeps running because it's in the calendar.", 0]], "cues": [0.05]}, "n_6_14": {"dur": 12.96, "text": "Time for the last drill of the season. Everything you've practiced arrives at once. Press play. Melissa will stop three times and ask you something. Take the time you need, and the video carries on when you're done.", "sents": [[0.03, "Time for the last drill of the season.", 0], [2.43, "Everything you've practiced arrives at once.", 0], [5.33, "Press play.", 1], [6.67, "Melissa will stop three times and ask you something.", 1], [9.85, "Take the time you need, and the video carries on when you're done.", 1]], "cues": [0.03, 5.33]}, "n_6_15": {"dur": 22.4, "text": "Your last Playbook week takes about an hour. Write one specific win for each pillar, and rate yourself again next to your Lesson 1 baseline. Choose one habit per pillar to keep and one thing to stop, and pick your focus pillar for the next ninety days. Then close the season in Part 6 of your Scorecard. The post-assessment comes at the end of this lesson.", "sents": [[0.03, "Your last Playbook week takes about an hour.", 0], [2.83, "Write one specific win for each pillar, and rate yourself again next to your Lesson 1 baseline.", 1], [8.87, "Choose one habit per pillar to keep and one thing to stop, and pick your focus pillar for the next ninety days.", 2], [16.07, "Then close the season in Part 6 of your Scorecard.", 3], [20.01, "The post-assessment comes at the end of this lesson.", 3]], "cues": [0.03, 2.83, 8.87, 16.07]}, "n_6_16": {"dur": 10.48, "text": "Your last Athleader Pro is Stephanie Johnson, the Momentum Maker. She turns adversity into acceleration, for teams and for herself. Press play to hear from her.", "sents": [[0.09, "Your last Athleader Pro is Stephanie Johnson, the Momentum Maker.", 0], [4.37, "She turns adversity into acceleration, for teams and for herself.", 0], [9.19, "Press play to hear from her.", 1]], "cues": [0.09, 9.19]}, "n_6_17": {"dur": 11.12, "text": "Stephanie's drill helps you realign under pressure, and it takes three minutes. Select Start the timer and work through each step. Tick I ran this drill when you're done.", "sents": [[0, "Stephanie's drill helps you realign under pressure, and it takes three minutes.", 0], [4.91, "Select Start the timer and work through each step.", 1], [8.79, "Tick I ran this drill when you're done.", 1]], "cues": [0, 4.91]}, "n_6_19_q0": {"dur": 7.6, "text": "A few questions to check the main ideas. In this system, what turns one good season into a lasting change?", "sents": [[0.05, "A few questions to check the main ideas.", 0], [3.19, "In this system, what turns one good season into a lasting change?", 0]], "cues": [0.05]}, "n_6_19_w0": {"dur": 6.0, "text": "Running the same ninety-day loop again, on a schedule: plan, execute, reflect and reset.", "sents": [[0, "Running the same ninety-day loop again, on a schedule: plan, execute, reflect and reset.", 0]], "cues": [0]}, "n_6_19_q1": {"dur": 3.84, "text": "Why name a specific moment for each pillar, rather than a general feeling?", "sents": [[0.07, "Why name a specific moment for each pillar, rather than a general feeling?", 0]], "cues": [0.07]}, "n_6_19_w1": {"dur": 4.96, "text": "A named moment shows you which strategy worked, so you know what to keep doing next season.", "sents": [[0, "A named moment shows you which strategy worked, so you know what to keep doing next season.", 0]], "cues": [0]}, "n_6_19_q2": {"dur": 5.52, "text": "Your Agility rating went from two to four, and Wellbeing stayed at two. What does that tell you?", "sents": [[0, "Your Agility rating went from two to four, and Wellbeing stayed at two.", 0], [4.51, "What does that tell you?", 0]], "cues": [0]}, "n_6_19_w2": {"dur": 5.76, "text": "The gap that closed is your win. The gap that didn't is a strong candidate for your next season's focus.", "sents": [[0.07, "The gap that closed is your win.", 0], [2.27, "The gap that didn't is a strong candidate for your next season's focus.", 0]], "cues": [0.07]}, "n_6_19_q3": {"dur": 9.84, "text": "Last one. The plan changes, a trusted colleague disagrees, and people are watching, all at the same time. What does a conditioned leader do first?", "sents": [[0.03, "Last one.", 0], [1.23, "The plan changes, a trusted colleague disagrees, and people are watching, all at the same time.", 0], [7.91, "What does a conditioned leader do first?", 0]], "cues": [0.03]}, "n_6_19_w3": {"dur": 7.12, "text": "Notice your own reaction first, then choose the next move on purpose. That's what every drill this season has practiced.", "sents": [[0.01, "Notice your own reaction first, then choose the next move on purpose.", 0], [4.71, "That's what every drill this season has practiced.", 0]], "cues": [0.01]}, "n_6_20": {"dur": 29.44, "text": "Before you finish, a quick recap. Name the win and keep the habit. A specific moment for each pillar is how the change sticks. The gap that closed is your win, and the gap that didn't is next season's focus. Your Lesson 1 baseline next to today's rating says it all. And the loop is the result: plan, execute, reflect and reset, with a check-in in your calendar every Friday. Select Download my answers for a Word copy of what you wrote today.", "sents": [[0.05, "Before you finish, a quick recap.", 0], [2.47, "Name the win and keep the habit.", 1], [4.97, "A specific moment for each pillar is how the change sticks.", 1], [8.65, "The gap that closed is your win, and the gap that didn't is next season's focus.", 2], [14.07, "Your Lesson 1 baseline next to today's rating says it all.", 2], [18.13, "And the loop is the result: plan, execute, reflect and reset, with a check-in in your calendar every Friday.", 3], [25.77, "Select Download my answers for a Word copy of what you wrote today.", 4]], "cues": [0.05, 2.47, 8.65, 18.13, 25.77]}, "n_E2": {"dur": 4.4, "text": "Type the code from the last page of the post-assessment, then select Submit.", "sents": [[0.09, "Type the code from the last page of the post-assessment, then select Submit.", 0]], "cues": [0.09]}, "n_E4": {"dur": 6.88, "text": "If you'd like to tell your network you've finished, copy this post and share it on LinkedIn. This step is optional.", "sents": [[0, "If you'd like to tell your network you've finished, copy this post and share it on LinkedIn.", 0], [5.11, "This step is optional.", 0]], "cues": [0]}, "ci_a": {"dur": 21.04, "text": "Pressure shows how you actually lead, and this is where you start to see the gap between instinct and intention. Take about thirty seconds on each of these. Write what actually went on in you, rather than what you think should have. Only you can see this, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0, "Pressure shows how you actually lead, and this is where you start to see the gap between instinct and intention.", 0], [6.61, "Take about thirty seconds on each of these.", 1], [9.05, "Write what actually went on in you, rather than what you think should have.", 1], [13.21, "Only you can see this, and it's saved here so you can come back to it.", 1], [17.65, "Select Save on each one as you go, then select Next.", 2]], "cues": [0, 6.61, 17.65]}, "ci_b": {"dur": 9.6, "text": "Now look at what you wrote, and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the honest one.", "sents": [[0, "Now look at what you wrote, and pick the pattern that's closest to it.", 0], [3.69, "There's no right answer.", 1], [5.31, "Naming a habit helps you catch it sooner next time, so pick the honest one.", 1]], "cues": [0, 3.69]}, "ci_c": {"dur": 16.0, "text": "Now run the Foundation Reset. Say your five words. Ask yourself for two next-best steps, and pick the one you'll do in the next ten minutes. Then take one breath. It takes about a minute and works best standing up, so do it now, before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.05, "Say your five words.", 1], [3.73, "Ask yourself for two next-best steps, and pick the one you'll do in the next ten minutes.", 1], [9.19, "Then take one breath.", 1], [11.11, "It takes about a minute and works best standing up, so do it now, before you move on.", 2]], "cues": [0, 2.05, 11.11]}, "kc_retry": {"dur": 2.88, "text": "Not quite. Have another look, then try again.", "sents": [[0.01, "Not quite.", 0], [1.13, "Have another look, then try again.", 0]], "cues": [0.01]}, "r2_n_G6": {"dur": 23.52, "text": "This assessment is your starting point. It asks how you lead today, and after Lesson 6 you'll answer the same questions so you can see what changed. It takes about five minutes, and your individual answers stay confidential. Select Next when you're ready, and it opens right here. With your results, you'll get your Growth Guide, showing where you stand on each of the Core 4 today.", "sents": [[0.03, "This assessment is your starting point.", 0], [2.43, "It asks how you lead today, and after Lesson 6 you'll answer the same questions so you can see what changed.", 0], [9.65, "It takes about five minutes, and your individual answers stay confidential.", 1], [14.37, "Select Next when you're ready, and it opens right here.", 1], [18.33, "With your results, you'll get your Growth Guide, showing where you stand on each of the Core 4 today.", 2]], "cues": [0.03, 9.65, 18.33]}, "r2_form_pre": {"dur": 12.4, "text": "Take your time with these. There are no right answers, and your individual answers stay confidential. When you submit, a short code appears on the last page. Note it down, then select Next.", "sents": [[0.01, "Take your time with these.", 0], [1.85, "There are no right answers, and your individual answers stay confidential.", 0], [6.27, "When you submit, a short code appears on the last page.", 0], [10.03, "Note it down, then select Next.", 0]], "cues": [0.01]}, "r2_code_pre": {"dur": 7.84, "text": "Type the code from the last page of the assessment, then select Submit. Lesson 1 opens as soon as the code is accepted.", "sents": [[0.01, "Type the code from the last page of the assessment, then select Submit.", 0], [4.97, "Lesson 1 opens as soon as the code is accepted.", 0]], "cues": [0.01]}, "r2_pulse": {"dur": 22.72, "text": "Every lesson ends with the same short Pulse Check, so you can see how you're changing over the season. It asks how often, in the last two weeks, you've shown each of the Core 4, and whether you did this lesson's reps. It takes under a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next and it opens right here.", "sents": [[0, "Every lesson ends with the same short Pulse Check, so you can see how you're changing over the season.", 0], [5.79, "It asks how often, in the last two weeks, you've shown each of the Core 4, and whether you did this lesson's reps.", 1], [13.25, "It takes under a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [20.37, "Select Next and it opens right here.", 2]], "cues": [0, 5.79, 13.25]}, "r2_form_pulse": {"dur": 8.88, "text": "Answer the five questions, then select Submit my Pulse Check. Your code appears on the last page. Note it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit my Pulse Check.", 0], [4.31, "Your code appears on the last page.", 0], [6.57, "Note it down, then select Next.", 0]], "cues": [0]}, "r2_code_pulse": {"dur": 6.8, "text": "Type the code from the last page of the Pulse Check, then select Submit. That completes the lesson.", "sents": [[0, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.61, "That completes the lesson.", 0]], "cues": [0]}, "r2_n_E1": {"dur": 16.16, "text": "You've finished all six lessons. The last step is the post-assessment: the same questions you answered before Lesson 1, so you can see what's changed, then a few about how your manager has led. It takes about eight minutes. Select Next and it opens right here.", "sents": [[0.03, "You've finished all six lessons.", 0], [2.39, "The last step is the post-assessment: the same questions you answered before Lesson 1, so you can see what's changed, then a few about how your manager has led.", 0], [11.97, "It takes about eight minutes.", 1], [13.99, "Select Next and it opens right here.", 1]], "cues": [0.03, 11.97]}, "r2_form_post": {"dur": 8.72, "text": "Answer for where you are now, not where you started. When you submit, your code appears on the last page. Note it down, then select Next.", "sents": [[0.01, "Answer for where you are now, not where you started.", 0], [3.45, "When you submit, your code appears on the last page.", 0], [6.59, "Note it down, then select Next.", 0]], "cues": [0.01]}, "r2_n_E3": {"dur": 19.76, "text": "Your Player-Coach has been part of this season with you. The 180 asks for your view of how they supported you, and they give their view of you in their own. It takes about five minutes, and it completes your course. Select Next to open it here. If you don't have a participating Player-Coach, select the option below instead.", "sents": [[0.09, "Your Player-Coach has been part of this season with you.", 0], [3.21, "The 180 asks for your view of how they supported you, and they give their view of you in their own.", 0], [9.65, "It takes about five minutes, and it completes your course.", 1], [12.77, "Select Next to open it here.", 1], [15.37, "If you don't have a participating Player-Coach, select the option below instead.", 1]], "cues": [0.09, 9.65]}, "r2_form_180_a": {"dur": 10.88, "text": "Rate how often your Player-Coach did each of these this season, then add a line or two if you'd like. Your code appears on the last page. Note it down, then select Next.", "sents": [[0.17, "Rate how often your Player-Coach did each of these this season, then add a line or two if you'd like.", 0], [6.29, "Your code appears on the last page.", 0], [8.63, "Note it down, then select Next.", 0]], "cues": [0.17]}, "r2_code_180": {"dur": 7.76, "text": "Type the code from the last page of the 180, then select Submit. That completes your course.", "sents": [[0.01, "Type the code from the last page of the 180, then select Submit.", 0], [5.51, "That completes your course.", 0]], "cues": [0.01]}, "r2_cert": {"dur": 13.6, "text": "Congratulations. You've completed the M.V.P. Accelerator, and this certificate is yours. Type your name the way you want it printed, then select Download my certificate. It saves as a PDF you can print or keep.", "sents": [[0.0, "Congratulations.", 0], [1.35, "You've completed the M.V.P. Accelerator, and this certificate is yours.", 0], [6.27, "Type your name the way you want it printed, then select Download my certificate.", 1], [11.15, "It saves as a PDF you can print or keep.", 1]], "cues": [0.0, 6.27]}, "r2_form_wall": {"dur": 11.28, "text": "The Wall of Fame is where each group leaves something for the next one. Share a moment from your season that showed you what had changed. This step is optional. When you're done, you can close the course.", "sents": [[0.07, "The Wall of Fame is where each group leaves something for the next one.", 0], [4.11, "Share a moment from your season that showed you what had changed.", 0], [7.67, "This step is optional.", 0], [9.23, "When you're done, you can close the course.", 0]], "cues": [0.07]}};
